pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {BANK_SAFE} from "../src/BANK_SAFE.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    BANK_SAFE c;

    function setUp() public {
        c = new BANK_SAFE();
    }

    function _run(address log, uint256 depositAmount) internal {
        depositAmount = bound(depositAmount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= depositAmount);
        try c.SetLogFile(log) {} catch { return; }
        try c.SetMinSum(0) {} catch { return; }
        try c.Initialized() {} catch { return; }
        uint256 beforeBal;
        try c.balances(address(this)) returns (uint256 __r) { beforeBal = __r; } catch { return; }
        try c.Deposit{value: depositAmount}() {} catch { return; }
        uint256 afterBal;
        try c.balances(address(this)) returns (uint256 __r) { afterBal = __r; } catch { return; }
        assertTrue(afterBal == beforeBal + depositAmount);
    }

    function testFuzz_run(address log, uint256 depositAmount) public {
        vm.assume(log.code.length == 0 && uint160(log) > 0xffff && log != address(this) && log != address(c) && log != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && log != 0x000000000000000000636F6e736F6c652e6c6f67 && log != 0x4e59b44847b379578588920cA78FbF26c0B4956C && log != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(log, depositAmount);
    }

    receive() external payable {}
}
